class ShoppingCart:
    def __init__(self):
        self.items = []

    def add(self, item, price):
        self.items.append((item, price))

    def count(self):
        return len(self.items)

    def total(self):
        return sum(price for _, price in self.items)


cart = ShoppingCart()
cart.add("bread", 3.50)
cart.add("milk", 2.25)
cart.add("coffee", 7.00)
print(f"Items: {cart.count()}")
print(f"Total: ${cart.total():.2f}")

