class Student:
    count = 0

    def __init__(self, name, score):
        self.name = name
        self.score = score
        Student.count += 1

    @classmethod
    def from_string(cls, text):
        name, score = text.split(",")
        return cls(name, int(score))

    @staticmethod
    def is_passing(score):
        return score >= 60


ana = Student.from_string("Ana,90")
ben = Student("Ben", 55)
cy = Student.from_string("Cy,72")
print(ana.name, ana.score)
print(f"Students: {Student.count}")
print(Student.is_passing(90), Student.is_passing(ben.score))

