class Order:
    count = 0

    def __init__(self, item, qty):
        self.item = item
        self.qty = qty
        Order.count += 1

    @classmethod
    def from_string(cls, text):
        item, qty = text.split(",")
        return cls(item, int(qty))

    @staticmethod
    def is_valid_qty(qty):
        return 1 <= qty <= 10


